def transform(grid):
    # The zeros that become 8 form the complement area bounded by the 5-shapes.
    # Encode observed orientation through 5-connected foreground component layout.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Task examples show 8 fills the zero area to the right of a vertical/horizontal
    # 5-boundary, and 7 marks a two-cell notch at the top boundary.
    # Conservative geometric rule: fill zeros enclosed by 5 barriers via flood-fill
    # from exterior, then mark topmost enclosed run 7.
    seen=set(); stack=[]
    for r in range(h):
        for c in range(w):
            if r in (0,h-1) or c in (0,w-1):
                if grid[r][c]==0 and (r,c) not in seen: seen.add((r,c)); stack.append((r,c))
    while stack:
        r,c=stack.pop()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and (rr,cc) not in seen:
                seen.add((rr,cc)); stack.append((rr,cc))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r,c) not in seen: out[r][c]=8
    return out
