    # structure and adjacent empty block regions become color 8; shallow upper
    # cavities become 7. Rules generalized from the three paired grids.
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Mark 8 where zeros are enclosed by foreground on both sides horizontally
    # or vertically, extending contiguous cavity runs.
    for r in range(h):
