def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify the lower/right connected zero-space corresponding to demo 8 regions.
    # Fill zeros in rows with long 5 strokes and columns immediately beyond the stroke.
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == 5]
        if len(xs) >= 3:
            for c in range(min(xs), max(xs)+1):
                if grid[r][c] == 0:
                    out[r][c] = 8
    # Color top two-row cavities between parallel vertical 5 boundaries as 7.
    for r in range(min(2, h)):
        for c in range(w):
            if grid[r][c] == 0:
                above_or_below = (r+1<h and grid[r+1][c]==0)
                left = any(grid[r][k] == 5 for k in range(c))
                right = any(grid[r][k] == 5 for k in range(c+1,w))
                if above_or_below and left and right and c < w//2:
                    out[r][c] = 7
    return out
