            if all(grid[r][left] == 5 and grid[r][right] == 5 for r in range(min(2,h))):
                if all(grid[r][c] == 0 for r in range(min(2,h)) for c in range(left+1,right)):
                    for r in range(min(2,h)):
                        for c in range(left+1,right): out[r][c] = 7
                    break
        else:
            continue
        break
    # Rectangular spaces between long parallel vertical strokes are filled with 8.
    bars = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= h-1]
    if len(bars) >= 2:
        left, right = bars[0], bars[-1]
        for r in range(h):
            for c in range(left+1, right):
                if grid[r][c] == 0: out[r][c] = 8
    return out
