def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    # A zero patch is a cavity when every cardinal exit is blocked by a 5
    # or by the grid boundary. Recolor the patch according to its location.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            S = set(cells)
            sealed = True
            for y, x in cells:
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in S:
                        sealed = False
            if sealed:
                color = 7 if any(y == 0 for y, x in cells) else 8
                for y, x in cells:
                    out[y][x] = color
    return out
