def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # In the demonstrations, one large background region bordered by the 5
    # strokes is recolored 8. Select zero-components with the strongest 5 border.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            stack = [(r,c)]; seen.add((r,c)); cells = []
            while stack:
                y,x = stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            border = sum(1 for y,x in cells for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 5)
            comps.append((border, cells))
    if comps:
        maxborder = max(b for b,cells in comps)
        for border,cells in comps:
            # Fill the dominant stroke-adjacent region(s), preserving sparse outside background.
            if border == maxborder and border >= 4:
                for r,c in cells:
                    out[r][c] = 8
    return out
