def transform(grid):
    from collections import deque
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=set(); walls=0
        while q:
          y,x=q.popleft(); cells.append((y,x))
          if y==0: edge.add('T')
          if y==h-1: edge.add('B')
          if x==0: edge.add('L')
          if x==w-1: edge.add('R')
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if not (0<=yy<h and 0<=xx<w): continue
            if grid[yy][xx]==5: walls+=1
            elif (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
        # Fill zero components screened on multiple sides by the 5 strokes;
        # use 7 for small upper pockets, 8 for large cavities.
        if walls >= 4 and len(edge)>=1 and walls >= len(cells):
          color=7 if len(cells)<=4 and 'T' in edge else 8
          for y,x in cells: out[y][x]=color
    return out
