def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            border5 = sum(1 for y,x in cells for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1))
                          if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 5)
            components.append((cells, border5))
    # Based on demos, the largest substantial zero region is recolored 8;
    # compact strongly 5-bordered pockets are recolored 7.
    substantial = [cells for cells, border in components if len(cells) >= 8]
    if substantial:
        cells = max(substantial, key=len)
        for r,c in cells:
            out[r][c] = 8
    for cells, border in components:
        if len(cells) <= 4 and border >= 2 * len(cells):
            for r,c in cells:
                out[r][c] = 7
    return out
